from decimal import Decimal, ROUND_HALF_UP


def parse_duration(text):
    """Return the duration described by `text` in whole milliseconds. See TASK.md."""
    if not isinstance(text, str):
        raise TypeError

    text = text.strip()

    if not text:
        raise ValueError

    # Check for leading sign
    negative = False
    if text[0] == '-':
        negative = True
        text = text[1:]
    elif text[0] == '+':
        raise ValueError

    if not text:
        raise ValueError

    # Units in order with their millisecond values
    unit_values = {
        'w': 604800000,
        'd': 86400000,
        'h': 3600000,
        'm': 60000,
        's': 1000,
        'ms': 1
    }

    unit_order = ['w', 'd', 'h', 'm', 's', 'ms']

    components = []
    i = 0
    last_unit_index = -1

    while i < len(text):
        # Parse a number
        if not (text[i].isdigit() or text[i] == '.'):
            raise ValueError

        num_start = i
        while i < len(text) and (text[i].isdigit() or text[i] == '.'):
            i += 1

        num_str = text[num_start:i]

        # Validate number format - fractions must have digits on both sides of the dot
        if '.' in num_str:
            parts = num_str.split('.')
            if len(parts) != 2 or not parts[0] or not parts[1]:
                raise ValueError

        number = Decimal(num_str)

        # Check no space between number and unit
        if i < len(text) and text[i] == ' ':
            raise ValueError

        # Parse unit
        if i >= len(text) or not text[i].isalpha():
            raise ValueError

        unit_start = i
        while i < len(text) and text[i].isalpha():
            i += 1

        unit = text[unit_start:i]

        if unit not in unit_values:
            raise ValueError

        # Check unit order - must be strictly descending
        unit_idx = unit_order.index(unit)
        if unit_idx <= last_unit_index:
            raise ValueError

        last_unit_index = unit_idx

        components.append((number, unit))

        # Handle space after unit
        if i < len(text):
            if text[i] == ' ':
                i += 1
                # Check for double space
                if i < len(text) and text[i] == ' ':
                    raise ValueError
            elif text[i].isdigit() or text[i] == '.':
                pass  # Continue the loop for next component
            else:
                raise ValueError

    # Validate that only the last component has a fraction
    for j, (number, unit) in enumerate(components[:-1]):
        if number % 1 != 0:
            raise ValueError

    # Calculate total milliseconds
    total_ms = Decimal(0)
    for number, unit in components:
        total_ms += number * Decimal(unit_values[unit])

    # Round to nearest millisecond with halves rounding away from zero
    result = int(total_ms.quantize(Decimal('1'), rounding=ROUND_HALF_UP))

    # Handle -0: negative zero should become positive zero
    if negative:
        if result == 0:
            return 0
        result = -result

    return result
